function validate([nums, x]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value in nums is an integer from 1 to 1000000.';
  if (!Number.isInteger(x) || x < 1 || x > 1000000) return 'x is an integer from 1 to 1000000.';
  return null;
}

