function maxScore(nums, x) {
  // Try every set of later indices to visit after index 0.
  const n = nums.length;
  let answer = -Infinity;
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    let score = nums[0];
    let last = 0;
    for (let j = 1; j < n; j++) {
      if (!(mask & (1 << (j - 1)))) continue;
      score += nums[j];
      if (nums[j] % 2 !== nums[last] % 2) score -= x;
      last = j;
    }
    answer = Math.max(answer, score);
  }
  return answer;
}

