function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000));
    const x = 1 + Math.floor(rand() ** 2 * 1000000);
    return [nums, x];
  }
  const n = 2 + Math.floor(rand() * 9);
  // Sometimes keep one parity so long runs without penalties appear.
  const oneParity = rand() < 0.2;
  const nums = Array.from({ length: n }, () => {
    const value = 1 + Math.floor(rand() * 12);
    return oneParity && value % 2 === 1 ? value + 1 : value;
  });
  const x = 1 + Math.floor(rand() * 12);
  return [nums, x];
}
